// The seam through the REAL verifier, against local fixtures only: the
// upstream is a temporary git repository on disk (a local path, no network),
// the recipe and fact bundle are generated by the real draft recorder from it,
// and the runner is the gate's own (its argument check, its child
// environment and its bounded exec). Only the repository address is mapped:
// the runner accepts the https://github.com/ shape and nothing else, so the
// test hands the child the local path at the one place the URL goes, and
// allows the local transport for that child. The mapping lives in this test
// file only; nothing in the package can set it.

var realSeamTags = []string{"v1.0.0", "v1.1.0", "v1.2.0", "v1.3.0"}

// localUpstream builds the fake upstream: four commits (the salt makes the
// commit ids differ between two upstreams of the same content), each with the
// fixture CRD directory, tagged (one annotated tag, to exercise the peeled
// lines of ls-remote).
func localUpstream(t *testing.T, salt string) string {
	t.Helper()
	dir := t.TempDir()
	gitIn(t, dir, "init", "-q")
	writeFile(t, filepath.Join(dir, filepath.FromSlash(obCRD)), []byte(obCRDDoc(obGroup, "v1")))
	writeFile(t, filepath.Join(dir, "README.md"), []byte("readme\n"))
	gitIn(t, dir, "add", "--all")
	for i, tag := range realSeamTags {
		gitIn(t, dir, "commit", "-q", "--allow-empty", "-m", fmt.Sprintf("%s %d", salt, i))
		if tag == "v1.1.0" {
			gitIn(t, dir, "tag", "-a", "-m", "annotated", tag)
		} else {
			gitIn(t, dir, "tag", tag)
		}
	}
	return dir
}

// localRunner is the gate's runner with the repository address mapped to a
// local path: the verifier's exact vector must pass the gate's own check first.
type localRunner struct {
	mu    sync.Mutex
	dir   string
	specs []targetdraft.ExecSpec
	res   []targetdraft.ExecResult
}

func (r *localRunner) Run(ctx context.Context, spec targetdraft.ExecSpec) targetdraft.ExecResult {
	r.mu.Lock()
	r.specs = append(r.specs, spec)
	r.mu.Unlock()
	if !runnerArgvOK(spec.Argv) {
		return targetdraft.ExecResult{Err: os.ErrPermission}
	}
	git := ""
	for _, c := range runnerGitPaths {
		if st, err := os.Stat(c); err == nil && st.Mode().IsRegular() {
			git = c
			break
		}
	}
	if git == "" {
		return targetdraft.ExecResult{Err: os.ErrNotExist}
	}
	argv := append([]string(nil), spec.Argv...)
	argv[len(runnerPrefix)] = r.dir
	env := make([]string, 0, len(spec.Env))
	for _, e := range spec.Env {
		if e == "GIT_ALLOW_PROTOCOL=https" {
			e = "GIT_ALLOW_PROTOCOL=file"
		}
		env = append(env, e)
	}
	home, err := os.MkdirTemp("", "prufyx-localrunner-")
	if err != nil {
		return targetdraft.ExecResult{Err: err}
	}
	defer os.RemoveAll(home)
	res := runnerExec(ctx, git, argv[1:], runnerChildEnv(targetdraft.ExecSpec{Env: env}, home), home)
	r.mu.Lock()
	r.res = append(r.res, res)
	r.mu.Unlock()
	return res
}

func (r *localRunner) calls() int {
	r.mu.Lock()
	defer r.mu.Unlock()
	return len(r.specs)
}

// realSeam is a seam fixture whose head carries a real recipe directory and
// the generated target of the fake upstream.
type realSeam struct {
	*seamFixture
	up     string
	runner *localRunner
	// seen is the last result of the real verifier.
	seen targetdraft.OnboardingVerifyResult
}

func newRealSeam(t *testing.T) *realSeam {
	t.Helper()
	f := newOnboardingFixture(t)
	up := localUpstream(t, "a")
	src := targetdraft.GitSource{Dir: up}
	in := targetdraft.Input{Slug: obSlug, Name: "Synthetic", Repo: obRepo, Catalog: "cncf", Tags: realSeamTags, Source: src, CollapseDirectories: true}
	res, err := targetdraft.Generate(in)
	if err != nil {
		t.Fatalf("generate: %v", err)
	}
	rd, err := targetdraft.RecordDraft(in, src, res.A, res.TableRow)
	if err != nil {
		t.Fatalf("record: %v", err)
	}
	ol := DefaultLayout().Onboarding
	if want := targetdraft.CrdVersionsDir + "/target-" + obSlug + ".json"; targetPath(ol, obSlug) != want || targetdraft.RecipesRoot != recipesRoot {
		t.Fatalf("layout and verifier disagree: %s vs %s", targetPath(ol, obSlug), want)
	}
	files := map[string][]byte{"recipe.json": rd.Recipe, "facts.bundle": rd.FactsBundle, "report.json": rd.Report, "table-row.json": rd.TableRow, "changelog.md": rd.Changelog}
	if len(rd.Rules) != 0 {
		files["rules.json"] = rd.Rules
	}
	for name, raw := range files {
		writeFile(t, filepath.Join(f.head.Root, filepath.FromSlash(recipesRoot+obSlug+"/"+name)), raw)
	}
	writeFile(t, filepath.Join(f.head.Root, filepath.FromSlash(targetPath(ol, obSlug))), rd.Target)
	f.follow(t)
	f.refresh()
	s := &realSeam{up: up, runner: &localRunner{dir: up}}
	s.seamFixture = seamFixtureOf(t, f)
	s.opts.AdmissionRunner = s.runner
	s.opts.AdmissionVerifier = func(in targetdraft.OnboardingVerifyInput) targetdraft.OnboardingVerifyResult {
		res := targetdraft.VerifyOnboarding(in)
		s.mu.Lock()
		s.seen = res
		s.mu.Unlock()
		return res
	}
	return s
}

// The layout flag stays off in the compiled default; the tests turn it on in
// their own copy only.
func TestRealSeamDefaultLayoutStaysOff(t *testing.T) {
	t.Parallel()
	if DefaultLayout().OnboardingAdmission.Enabled {
		t.Fatal("the compiled default layout turned the admission seam on")
	}
}

// Positive: the real verifier, the real recipe and fact bundle, the real
// binding through the gate's runner against a local upstream. The seam hands
// the frozen decision a result that binds to the gate's own facts, so the
// decision carries no verify-pr reason.
func TestRealSeamPositiveEndToEnd(t *testing.T) {
	t.Parallel()
	s := newRealSeam(t)
	r := s.gate(nil)
	if s.seen.Mode != targetdraft.OnboardingVerifyMode || s.seen.Outcome != "pass" {
		t.Fatalf("real verifier: %+v", s.seen)
	}
	if s.runner.calls() != 1 {
		t.Fatalf("runner called %d times", s.runner.calls())
	}
	spec := s.runner.specs[0]
	if len(spec.Argv) != len(runnerPrefix)+1+2*len(realSeamTags) || spec.Argv[len(runnerPrefix)] != "https://github.com/"+obOwnerRepo+".git" {
		t.Fatalf("upstream vector %v", spec.Argv)
	}
	if res := s.runner.res[0]; res.Err != nil || res.Exit != 0 || res.TimedOut || len(res.Stdout) == 0 {
		t.Fatalf("local ls-remote: %+v", res)
	}
	d := r.OnboardingAdmission
	if d == nil {
		t.Fatal("no decision")
	}
	if got := verifyReasons(d); len(got) != 0 {
		t.Fatalf("verify-pr reasons on a real pass: %v (decision %+v)", got, d.Reasons)
	}
	if d.VerifyPr.Outcome != "pass" || !d.VerifyPr.BindingVerified || d.VerifyPr.RecipeChange != "new" || d.VerifyPr.Eligible ||
		d.VerifyPr.BaseSHA != s.base || d.VerifyPr.HeadSHA != s.head || d.VerifyPr.ChangedPathsSHA256 != d.PathSetSHA {
		t.Fatalf("bound member %+v (path set %s)", d.VerifyPr, d.PathSetSHA)
	}
	if !admitValidDigest(d.VerifyPr.BindingDigest) || len(d.VerifyPr.Slugs) != 1 || d.VerifyPr.Slugs[0] != obSlug {
		t.Fatalf("binding %+v", d.VerifyPr)
	}
	// Nothing here is merge authority: an owner fixture with no allowlist is
	// not admitted, and the seam never turns automatic merging on.
	if d.Admitted || r.AutoMerge.Eligible {
		t.Fatalf("admitted %v auto %v", d.Admitted, r.AutoMerge.Eligible)
	}
}

// Negative: a tag of the upstream is not the commit the recipe and the bundle
// name. The real binding refuses; no result is handed on.
func TestRealSeamTagMismatchRefused(t *testing.T) {
	t.Parallel()
	s := newRealSeam(t)
	s.runner.dir = localUpstream(t, "b") // same tags, other commits
	r := s.gate(nil)
	if s.seen.Outcome != "fail" || s.seen.Harness || !containsStr(s.seen.Reasons, "binding-mismatch") {
		t.Fatalf("verifier: %+v", s.seen)
	}
	if s.runner.calls() != 1 {
		t.Fatalf("runner called %d times", s.runner.calls())
	}
	d := r.OnboardingAdmission
	if d == nil || d.Admitted || !containsStr(d.Reasons, AdmitReasonSeamFailed) || d.VerifyPr != (VerifyPrBinding{}) {
		t.Fatalf("decision %+v", d)
	}
	seamOnly(t, s.direct(nil), AdmitReasonSeamFailed)
}

// Negative: one more changed path than the batch allows. The head commit,
// trees and options all carry it (so the tree checks pass); the real verifier
// refuses the path outside the allowlist before any network use.
func TestRealSeamExtraChangedPathRefused(t *testing.T) {
	t.Parallel()
	s := newRealSeam(t)
	s.gate(nil)
	before := s.runner.calls()
	head2 := cloneTree(t, s.f.head)
	writeFile(t, filepath.Join(head2.Root, "cli", "knowledge", "unrelated.json"), []byte("{}\n"))
	repo := t.TempDir()
	gitIn(t, repo, "init", "--bare", "-q")
	base := admissionCommit(t, repo, s.f.base, "")
	head := admissionCommit(t, repo, head2, base)
	gitIn(t, repo, "update-ref", admissionBaseRef, base)
	gitIn(t, repo, "update-ref", admissionHeadRef, head)
	in := s.direct(func(o *Options, _ *OnboardingAdmissionInput) {
		g := *o.OnboardingGit
		g.GitDir, g.BaseCommit, g.HeadCommit = repo, base, head
		o.OnboardingGit, o.Head, o.HeadSHA = &g, head2, head
	})
	seamOnly(t, in, AdmitReasonSeamFailed)
	if s.seen.Outcome != "fail" || !containsStr(s.seen.Reasons, targetdraft.OnbReasonOutside) {
		t.Fatalf("verifier: %+v", s.seen)
	}
	if s.runner.calls() != before {
		t.Fatal("the network was used for a change that failed the local checks")
	}
}

func containsStr(list []string, s string) bool {
	for _, x := range list {
		if x == s {
			return true
		}
	}
	return false
}
